/**
 * CinematicDirector — the one owner of the Map3D camera.
 *
 * Modes: orbitEarth → dive → frame (Atlas / Trip focus) → chase (Watch travel)
 * ↔ dwell / memory orbits ↔ pause (living pause) → finale → recap, plus a
 * `user` mode while the viewer drags/zooms. Per-frame follow uses critically
 * damped springs on heading, log-range and tilt so nothing ever snaps.
 */

import {
  type Camera3D,
  type FrameOptions,
  type LngLatBoundsLike,
  type Spring,
  type TravelMode,
  type Viewport,
  angleDiff,
  angleSpringStep,
  bearingBetween,
  cameraForBounds,
  clamp,
  haversineMeters,
  headingBlendForRange,
  lowerThirdOffset,
  mixHeading,
  normalizeHeading,
  offsetAlongBearing,
  rangeForScreenSpeed,
  springStep,
  tiltForRange,
} from "./camera-math";
import type { Google3DScene } from "./google-scene3d";

export type DirectorMode =
  | "idle"
  | "orbitEarth"
  | "dive"
  | "frame"
  | "chase"
  | "dwell"
  | "memory"
  | "pause"
  | "finale"
  | "recap"
  | "user";

export type ChaseSample = {
  lat: number;
  lng: number;
  /** Local road course in degrees. */
  bearing: number;
  /** Overall leg heading (start → end); followed when the camera is far away. */
  legBearing?: number;
  mode: TravelMode;
  /** Wall-clock seconds since the previous sample. */
  wallDt: number;
  /**
   * On-screen ground speed from the playback engine (m/s). When present the
   * range policy follows it directly — no wall-sample EMA lag, no seek spikes.
   */
  speedMps?: number;
};

export type DirectorOptions = {
  viewport: () => Viewport;
  reducedMotion?: () => boolean;
  /** Bank the camera a few degrees into turns (off by default). */
  enableRoll?: boolean;
};

/** Critically damped chase — kept soft so highway legs do not whip the cab (~105°/s was too snappy). */
const HEADING_OMEGA = 0.95;
const RANGE_OMEGA = 0.7;
const TILT_OMEGA = 0.85;
const WRITE_INTERVAL_MS = 33;
const SPEED_EMA = 0.08;
/** Soft keep-in-view while the viewer explores — rate-limited like Mapbox panBy. */
const KEEP_IN_VIEW_MS = 180;

export class CinematicDirector {
  mode: DirectorMode = "idle";
  private heading: Spring = { value: 0, velocity: 0 };
  private logRange: Spring = { value: Math.log(1200), velocity: 0 };
  private tilt: Spring = { value: 64, velocity: 0 };
  private speedEma = 0;
  private lastSample: { lat: number; lng: number; t: number } | null = null;
  private lastWrite = 0;
  private lastKeepInView = 0;
  private sequence = 0;
  private lastOrbitKey = "";

  constructor(
    private scene: Google3DScene,
    private opts: DirectorOptions,
  ) {}

  private reduced(): boolean {
    return !!this.opts.reducedMotion?.();
  }

  /** Any queued story sequence checks this token so a newer action cancels it. */
  private nextToken(): number {
    this.sequence += 1;
    return this.sequence;
  }

  private alive(token: number): boolean {
    return token === this.sequence;
  }

  cancel(): void {
    this.nextToken();
    this.scene.stopAnimation();
  }

  // ── Seeding / handoff ────────────────────────────────────────────────────

  /** Copy the live camera into the springs so the next chase frame continues from it. */
  reseedFromCamera(): void {
    const cam = this.scene.getCamera();
    this.heading = { value: normalizeHeading(cam.heading), velocity: 0 };
    this.logRange = { value: Math.log(clamp(cam.range, 60, 14_000_000)), velocity: 0 };
    this.tilt = { value: clamp(cam.tilt, 0, 82), velocity: 0 };
    this.lastSample = null;
  }

  resetMotion(): void {
    this.speedEma = 0;
    this.lastSample = null;
  }

  userGestureBegin(): void {
    if (this.mode === "user") return;
    this.nextToken();
    this.scene.stopAnimation();
    this.mode = "user";
  }

  userGestureEnd(): void {
    if (this.mode !== "user") return;
    this.reseedFromCamera();
    this.mode = "idle";
  }

  isUserControlled(): boolean {
    return this.mode === "user";
  }

  // ── Framing ──────────────────────────────────────────────────────────────

  setCamera(cam: Partial<Camera3D>): void {
    this.nextToken();
    this.scene.stopAnimation();
    this.scene.setCamera(cam);
    this.reseedFromCamera();
    this.mode = "frame";
  }

  async flyTo(cam: Partial<Camera3D>, durationMs: number): Promise<void> {
    const token = this.nextToken();
    this.mode = "frame";
    this.scene.stopAnimation();
    await this.scene.flyTo(cam, this.reduced() ? 0 : durationMs);
    if (this.alive(token)) this.reseedFromCamera();
  }

  cameraForBounds(bounds: LngLatBoundsLike, frame: FrameOptions): Camera3D {
    return cameraForBounds(bounds, this.opts.viewport(), { ...frame, fovDeg: frame.fovDeg ?? this.scene.getFov() });
  }

  frameBounds(bounds: LngLatBoundsLike, frame: FrameOptions & { durationMs?: number }): Promise<void> {
    const cam = this.cameraForBounds(bounds, frame);
    return this.flyTo(cam, frame.durationMs ?? 1200);
  }

  // ── Story: Earth → Atlas ─────────────────────────────────────────────────

  /**
   * Open on the globe with the routes as ribbons, drift a quarter turn, then
   * dive to the Atlas frame (north-up, bird's-eye).
   */
  async earthIntro(bounds: LngLatBoundsLike, frame: FrameOptions, timings = { orbitMs: 5200, diveMs: 3400 }): Promise<void> {
    const token = this.nextToken();
    const target = this.cameraForBounds(bounds, frame);
    if (this.reduced()) {
      this.scene.setCamera(target);
      this.reseedFromCamera();
      this.mode = "frame";
      return;
    }
    this.mode = "orbitEarth";
    const globe: Camera3D = {
      lat: (bounds.north + bounds.south) / 2 - 6,
      lng: (bounds.east + bounds.west) / 2,
      range: 11_500_000,
      tilt: 14,
      heading: 330,
    };
    this.scene.setCamera(globe);
    await this.scene.flyAround(globe, timings.orbitMs, 0.25);
    if (!this.alive(token)) return;
    this.mode = "dive";
    await this.scene.flyTo(target, timings.diveMs);
    if (!this.alive(token)) return;
    this.reseedFromCamera();
    this.mode = "frame";
  }

  // ── Watch: chase ─────────────────────────────────────────────────────────

  /** Per-frame follow. While the viewer holds the camera, soft keep-in-view only. */
  chase(sample: ChaseSample): void {
    if (this.mode === "user") {
      this.keepInView(sample);
      return;
    }
    if (this.mode !== "chase") {
      // Coming out of an orbit / frame: take over smoothly from wherever the camera is.
      this.nextToken();
      this.scene.stopAnimation();
      this.reseedFromCamera();
      this.mode = "chase";
      this.lastOrbitKey = "";
      // First frame after handoff must write immediately so the car is framed.
      this.lastWrite = 0;
    }

    const now = performance.now();
    const dt = clamp(sample.wallDt || 1 / 60, 1 / 240, 0.1);
    if (sample.speedMps != null && Number.isFinite(sample.speedMps)) {
      // Deterministic speed from the timeline: the range spring below is the only smoothing needed.
      this.speedEma = Math.max(0, sample.speedMps);
    } else if (this.lastSample) {
      const d = haversineMeters(this.lastSample.lat, this.lastSample.lng, sample.lat, sample.lng);
      const elapsed = Math.max(1 / 240, (now - this.lastSample.t) / 1000);
      const v = d / elapsed;
      // Ignore teleports (seek) — they would blow the range to the ceiling.
      if (d < 250_000) this.speedEma = this.speedEma ? this.speedEma + (v - this.speedEma) * SPEED_EMA : v;
    }
    this.lastSample = { lat: sample.lat, lng: sample.lng, t: now };

    const targetRange = rangeForScreenSpeed(this.speedEma, sample.mode);
    this.logRange = springStep(this.logRange, Math.log(targetRange), dt, RANGE_OMEGA);
    const range = Math.exp(this.logRange.value);

    const targetTilt = tiltForRange(range);
    this.tilt = springStep(this.tilt, targetTilt, dt, TILT_OMEGA);

    const blend = headingBlendForRange(range);
    const legHeading = sample.legBearing != null ? sample.legBearing : sample.bearing;
    const targetHeading = mixHeading(sample.bearing, legHeading, blend);
    // Catch up faster on sharp bends so the car does not slide out of frame.
    const headingErr = Math.abs(angleDiff(this.heading.value, targetHeading));
    const headingOmega =
      headingErr > 35 ? HEADING_OMEGA * 1.55 : headingErr > 18 ? HEADING_OMEGA * 1.25 : HEADING_OMEGA;
    this.heading = angleSpringStep(this.heading, targetHeading, dt, headingOmega);

    if (now - this.lastWrite < WRITE_INTERVAL_MS) return;
    this.lastWrite = now;

    const letterbox =
      typeof document !== "undefined" &&
      document.body.classList.contains("mock-b") &&
      document.body.classList.contains("watching");
    // Classic Watch: lower-third chase. Mock B letterbox: keep the car near the
    // film-gate center so the frame doesn't look stuck under the title card.
    // Shrink look-ahead while the heading spring is whipping — a full-length
    // offset with a reversing bearing flips the frame ahead↔behind of the car.
    const turnDamp = clamp(1 - Math.abs(this.heading.velocity) / 95, 0.18, 1);
    const ahead =
      lowerThirdOffset(range, this.tilt.value, this.scene.getFov()) *
      (letterbox ? 0.12 : 1) *
      turnDamp;
    const [lng, lat] = offsetAlongBearing(sample.lng, sample.lat, this.heading.value, ahead);
    const roll = this.opts.enableRoll ? clamp(-this.heading.velocity * 0.06, -3, 3) : 0;
    this.scene.setCamera({
      lat,
      lng,
      range,
      tilt: letterbox ? Math.min(this.tilt.value, 48) : this.tilt.value,
      heading: this.heading.value,
      roll,
    });
    this.scene.setVehicleScale(range);
  }

  /**
   * Viewer owns range/tilt/heading; only nudge look-at when the vehicle leaves
   * a comfortable margin of the ground footprint (Mapbox keep-in-view analogue).
   */
  keepInView(sample: { lat: number; lng: number }): void {
    if (this.mode !== "user") return;
    if (sample.lat == null || sample.lng == null) return;
    const now = performance.now();
    if (now - this.lastKeepInView < KEEP_IN_VIEW_MS) return;
    this.lastKeepInView = now;

    const cam = this.scene.getCamera();
    const dist = haversineMeters(cam.lat, cam.lng, sample.lat, sample.lng);
    const fov = this.scene.getFov();
    const halfSpan = Math.max(40, cam.range * Math.tan((fov / 2) * (Math.PI / 180)) * 0.9);
    const margin = halfSpan * 0.55;
    if (dist <= margin) return;

    const excess = dist - margin;
    const ease = excess > halfSpan ? 0.48 : excess > halfSpan * 0.5 ? 0.3 : 0.18;
    const brg = bearingBetween(cam.lat, cam.lng, sample.lat, sample.lng);
    const [lng, lat] = offsetAlongBearing(cam.lng, cam.lat, brg, excess * ease);
    this.scene.setCamera({
      lat,
      lng,
      range: cam.range,
      tilt: cam.tilt,
      heading: cam.heading,
      roll: cam.roll,
    });
  }

  currentRange(): number {
    return Math.exp(this.logRange.value);
  }

  // ── Watch: orbits ────────────────────────────────────────────────────────

  private async orbit(
    key: string,
    mode: DirectorMode,
    center: { lat: number; lng: number },
    cam: { range: number; tilt: number },
    approachMs: number,
    orbitMs: number,
    rounds: number,
  ): Promise<void> {
    if (this.mode === "user") return;
    if (this.lastOrbitKey === key && this.mode === mode) return;
    this.lastOrbitKey = key;
    const token = this.nextToken();
    this.mode = mode;
    const heading = this.heading.value;
    const target: Camera3D = { lat: center.lat, lng: center.lng, range: cam.range, tilt: cam.tilt, heading };
    if (this.reduced()) {
      this.scene.stopAnimation();
      this.scene.setCamera(target);
      this.reseedFromCamera();
      return;
    }
    this.scene.stopAnimation();
    await this.scene.flyTo(target, approachMs);
    if (!this.alive(token)) return;
    await this.scene.flyAround(target, orbitMs, rounds);
    if (!this.alive(token)) return;
    this.reseedFromCamera();
  }

  /** Charger / overnight stop: swoop in and drift around the spot. */
  dwell(center: { lat: number; lng: number }, key: string, kind: "charge" | "stay" | "other" = "other"): void {
    const range = kind === "stay" ? 520 : kind === "charge" ? 680 : 760;
    void this.orbit(`dwell:${key}`, "dwell", center, { range, tilt: 63 }, 900, 42_000, 1);
  }

  /** Photo moment: tight third-turn orbit while the polaroid rises. */
  memory(center: { lat: number; lng: number }, key: string): void {
    void this.orbit(`memory:${key}`, "memory", center, { range: 420, tilt: 66 }, 800, 7000, 0.34);
  }

  private pauseCenter: { lat: number; lng: number } | null = null;

  /** Living pause: never a frozen frame — one slow round per minute around the car. */
  pause(center: { lat: number; lng: number }): void {
    if (this.mode === "user") return;
    // Same spot while already orbiting (repeated pause / scrub events): keep the orbit going.
    if (
      this.mode === "pause" &&
      this.pauseCenter &&
      haversineMeters(this.pauseCenter.lat, this.pauseCenter.lng, center.lat, center.lng) < 30
    ) {
      return;
    }
    this.pauseCenter = { lat: center.lat, lng: center.lng };
    const token = this.nextToken();
    this.mode = "pause";
    const cur = this.scene.getCamera();
    const range = clamp(cur.range, 450, 6000);
    const target: Camera3D = {
      lat: center.lat,
      lng: center.lng,
      range,
      tilt: clamp(Math.max(cur.tilt, 58), 50, 70),
      heading: cur.heading,
    };
    if (this.reduced()) {
      this.scene.setCamera(target);
      return;
    }
    this.scene.stopAnimation();
    void this.scene.flyTo(target, 1100).then(() => {
      if (!this.alive(token)) return;
      return this.scene.flyAround(target, 60_000, 30);
    });
  }

  /** Resume from pause / orbit — the next chase() frame takes over smoothly. */
  resume(): void {
    if (this.mode === "user") return;
    this.nextToken();
    this.scene.stopAnimation();
    this.reseedFromCamera();
    this.mode = "idle";
    this.lastOrbitKey = "";
  }

  // ── Finale ───────────────────────────────────────────────────────────────

  /**
   * Orbit the destination while the end card counts up, then fly a recap
   * over route keyframes and settle on the full-route frame.
   */
  async finale(
    dest: { lat: number; lng: number },
    keyframes: Array<{ lat: number; lng: number }>,
    finalFrame: { bounds: LngLatBoundsLike; frame: FrameOptions },
  ): Promise<void> {
    const token = this.nextToken();
    this.mode = "finale";
    const cur = this.scene.getCamera();
    const orbitCam: Camera3D = { lat: dest.lat, lng: dest.lng, range: 1400, tilt: 60, heading: cur.heading };
    const settle = this.cameraForBounds(finalFrame.bounds, finalFrame.frame);
    if (this.reduced()) {
      this.scene.setCamera(settle);
      this.reseedFromCamera();
      this.mode = "frame";
      return;
    }
    this.scene.stopAnimation();
    await this.scene.flyTo(orbitCam, 1600);
    if (!this.alive(token)) return;
    await this.scene.flyAround(orbitCam, 14_000, 1);
    if (!this.alive(token)) return;
    this.mode = "recap";
    const frames = keyframes.slice(0, 8);
    for (let i = 0; i < frames.length; i++) {
      const k = frames[i];
      const next = frames[i + 1] || frames[i];
      const hop = haversineMeters(k.lat, k.lng, next.lat, next.lng);
      const range = clamp(hop * 1.6, 12_000, 400_000);
      const heading = i < frames.length - 1 ? this.bearingTo(k, next) : settle.heading;
      await this.scene.flyTo({ lat: k.lat, lng: k.lng, range, tilt: 55, heading }, 2600);
      if (!this.alive(token)) return;
    }
    await this.scene.flyTo(settle, 2400);
    if (!this.alive(token)) return;
    this.reseedFromCamera();
    this.mode = "frame";
  }

  private bearingTo(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
    const φ1 = (a.lat * Math.PI) / 180;
    const φ2 = (b.lat * Math.PI) / 180;
    const Δλ = ((b.lng - a.lng) * Math.PI) / 180;
    const y = Math.sin(Δλ) * Math.cos(φ2);
    const x = Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
    return normalizeHeading((Math.atan2(y, x) * 180) / Math.PI);
  }
}
