/**
 * Satellite-first per-trip route palette.
 *
 * Stable hash of trip id → color so shelves, atlas ribbons and Watch trails
 * stay in sync across reloads without reshuffling when trip order changes.
 *
 * Tuned for Mapbox satellite / Google Photorealistic basemaps (greens, browns,
 * mountain darks, water). Prefer bright, high-chroma, light-enough strokes:
 * cyan, coral, gold, magenta, ice-blue, lime. Avoid forest/olive/muddy browns
 * that vanish into the terrain. Cohesive travel-diary set — not neon spam,
 * not purple-glow AI defaults.
 */

export const DIARY_TRIP_PALETTE = [
  "#3EC7E0", // arctic cyan
  "#FF7A6E", // coral
  "#F0C04A", // gold
  "#E85A9B", // magenta rose
  "#7AD4F0", // ice blue
  "#A8E063", // lime
  "#FF9A5C", // apricot
  "#5BB8FF", // sky
  "#FF6BA8", // pink punch
  "#2DD4BF", // turquoise
  "#FFB347", // amber
  "#FFE066", // sunlight
  "#FF6B4A", // vermillion
  "#64D2FF", // brand cyan
  "#B8E986", // spring lime
  "#FF8FAB", // blush
  "#4ECDC4", // sea mint
  "#F7C948", // honey
  "#89C4F4", // powder blue
  "#FF8C69", // salmon
  "#7EE787", // mint lime
  "#E8A0BF", // soft rose
  "#56CCF2", // bright sky
  "#FFA07A", // light salmon
] as const;

/**
 * Soft cool slate used only as a thin under-casing for contrast —
 * never pure black, never the primary stroke.
 */
export const ROUTE_CASING_COLOR = "#1c2f3a";

/** Lighten a hex toward white for glow / hover (amount 0–1). */
export function lightenHex(hex: string, amount = 0.28): string {
  const h = String(hex || "").replace("#", "");
  if (h.length !== 6) return hex || "#c4d4e0";
  const n = parseInt(h, 16);
  const r = (n >> 16) & 255;
  const g = (n >> 8) & 255;
  const b = n & 255;
  const mix = (c: number) => Math.min(255, Math.round(c + (255 - c) * amount));
  return `#${[mix(r), mix(g), mix(b)].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

/** Glow tint — slightly lighter than the core so bloom reads on satellite. */
export function glowColorForTrip(tripColor: string, emphasis: "dim" | "normal" | "hot" = "normal"): string {
  if (emphasis === "dim") return lightenHex(tripColor, 0.1);
  if (emphasis === "hot") return lightenHex(tripColor, 0.42);
  return lightenHex(tripColor, 0.22);
}

/** FNV-1a → palette index. */
export function colorForTripId(tripId: string): string {
  const id = String(tripId || "");
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const idx = Math.abs(h) % DIARY_TRIP_PALETTE.length;
  return DIARY_TRIP_PALETTE[idx];
}
