/**
 * BufferGovernor — congestion control for the playback clock.
 *
 * A video player buffers when the network falls behind; a map replay has to
 * do the same when tiles fall behind the car. The legacy loop hard-toggled the
 * clock 1× ↔ 0.1× on `areTilesLoaded()` every frame, which stuttered on the
 * highway and crawled forever in software GL. This governor instead:
 *
 * - keeps an EMA of basemap readiness (Mapbox `areTilesLoaded`; `null` when
 *   the renderer has no signal, e.g. Photorealistic 3D — never gate on
 *   `isSteady` per frame, the moving camera is never "steady"),
 * - keeps an EMA of frame time so a struggling GPU also slows the car
 *   (smaller per-frame motion, fewer new tiles per second),
 * - eases the rate multiplier towards a target with asymmetric time constants
 *   (slow down fast, recover gently) and never below `floor`,
 * - raises `buffering` with hysteresis so the HUD can say "catching up" only
 *   for sustained slowdowns, not single dropped frames.
 */

export interface GovernorSample {
  /** Basemap ready this frame; `null` when the renderer gives no signal. */
  ready: boolean | null;
  /** Wall ms since the previous frame (clamped inside). */
  frameMs: number;
  /** Wall clock now, ms. */
  now: number;
}

export interface GovernorOptions {
  /** Lowest rate multiplier — the drive never stops for tiles. */
  floor?: number;
  readinessTauMs?: number;
  frameTauMs?: number;
  /** Time constant when the target is below the current multiplier. */
  slowTauMs?: number;
  /** Time constant when recovering towards 1. */
  recoverTauMs?: number;
  /** `buffering` turns on below this multiplier … */
  bufferingBelow?: number;
  /** … after being below for this long … */
  bufferingAfterMs?: number;
  /** … and clears above this multiplier. */
  clearAbove?: number;
  /** Frames longer than this (ms) start capping the rate. */
  frameBudgetMs?: number;
  /** Readiness above this is "healthy" (rate 1). Continuous panning is rarely 100 % ready. */
  readyHealthy?: number;
  /** Readiness below this is "starved" (rate = floor). */
  readyStarved?: number;
  /** Disable entirely (rate 1, never buffering). */
  disabled?: boolean;
}

const DEFAULTS: Required<GovernorOptions> = {
  floor: 0.35,
  readinessTauMs: 400,
  frameTauMs: 600,
  slowTauMs: 220,
  recoverTauMs: 900,
  bufferingBelow: 0.6,
  bufferingAfterMs: 450,
  clearAbove: 0.85,
  frameBudgetMs: 45,
  readyHealthy: 0.7,
  readyStarved: 0.25,
  disabled: false,
};

const MAX_FRAME_MS = 250;

function ease(current: number, target: number, dt: number, tau: number): number {
  if (tau <= 0) return target;
  return current + (target - current) * (1 - Math.exp(-dt / tau));
}

export class BufferGovernor {
  readonly opts: Required<GovernorOptions>;
  /** 0..1 — EMA of basemap readiness. */
  readiness = 1;
  /** EMA of frame time, ms. */
  frameEma = 16.7;
  /** Current clock multiplier in `[floor, 1]`. */
  multiplier = 1;
  buffering = false;
  private lowSince = 0;
  private listeners = new Set<(buffering: boolean) => void>();

  constructor(opts: GovernorOptions = {}) {
    this.opts = { ...DEFAULTS, ...opts };
  }

  onBuffering(fn: (buffering: boolean) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  reset(): void {
    this.readiness = 1;
    this.frameEma = 16.7;
    this.multiplier = 1;
    this.lowSince = 0;
    this.setBuffering(false);
  }

  /** Target multiplier for the current EMAs (before easing). */
  target(): number {
    const o = this.opts;
    if (o.disabled) return 1;
    const readySpan = Math.max(1e-6, o.readyHealthy - o.readyStarved);
    const readyT = Math.min(1, Math.max(0, (this.readiness - o.readyStarved) / readySpan));
    let target = o.floor + (1 - o.floor) * readyT;
    // A GPU that cannot hold the frame budget gets a smaller step per frame.
    const frameCap = Math.min(1, Math.max(o.floor, 1 - (this.frameEma - o.frameBudgetMs) / 120));
    target = Math.min(target, frameCap);
    return Math.max(o.floor, Math.min(1, target));
  }

  /** Feed one frame; returns the multiplier to apply this frame. */
  sample(s: GovernorSample): number {
    const o = this.opts;
    if (o.disabled) {
      this.multiplier = 1;
      this.setBuffering(false);
      return 1;
    }
    const dt = Math.min(MAX_FRAME_MS, Math.max(0, s.frameMs || 0));
    if (dt <= 0) return this.multiplier;
    if (s.ready === null) {
      // No signal: relax towards "fine" so only frame time governs.
      this.readiness = ease(this.readiness, 1, dt, o.readinessTauMs);
    } else {
      this.readiness = ease(this.readiness, s.ready ? 1 : 0, dt, o.readinessTauMs);
    }
    this.frameEma = ease(this.frameEma, dt, dt, o.frameTauMs);
    const target = this.target();
    const tau = target < this.multiplier ? o.slowTauMs : o.recoverTauMs;
    this.multiplier = Math.max(o.floor, Math.min(1, ease(this.multiplier, target, dt, tau)));
    if (this.multiplier < o.bufferingBelow) {
      if (!this.lowSince) this.lowSince = s.now;
      if (!this.buffering && s.now - this.lowSince >= o.bufferingAfterMs) this.setBuffering(true);
    } else {
      this.lowSince = 0;
      if (this.buffering && this.multiplier > o.clearAbove) this.setBuffering(false);
    }
    return this.multiplier;
  }

  private setBuffering(on: boolean): void {
    if (this.buffering === on) return;
    this.buffering = on;
    this.listeners.forEach((fn) => fn(on));
  }
}
